package software.amazon.awssdk.v2migration;

import java.util.HashSet;
import java.util.Set;
import org.openrewrite.ExecutionContext;
import org.openrewrite.Recipe;
import org.openrewrite.TreeVisitor;
import org.openrewrite.java.JavaIsoVisitor;
import org.openrewrite.java.tree.Expression;
import org.openrewrite.java.tree.J;
import org.openrewrite.java.tree.JavaType;
import org.openrewrite.java.tree.TypeUtils;
import software.amazon.awssdk.annotations.SdkInternalApi;
import software.amazon.awssdk.utils.StringUtils;
import software.amazon.awssdk.utils.internal.CodegenNamingUtils;
import software.amazon.awssdk.v2migration.internal.utils.SdkTypeUtils;

/**
 * Transforms V1 enum constants written in pascal case to the screaming snake case convention used by V2.
 */
@SdkInternalApi
public class EnumCasingToV2 extends Recipe {

    private static Set<String> ENUMS = new HashSet<>();

    @Override
    public String getDisplayName() {
        return "V1 Enum Casing to V2";
    }

    @Override
    public String getDescription() {
        return "Transforms V1 enum constants from pascal case to screaming snake case for v2.";
    }

    @Override
    public TreeVisitor<?, ExecutionContext> getVisitor() {
        return new Visitor();
    }

    private static String v2Casing(String enumStr) {
        enumStr = enumStr.replaceAll("textORcsv", "TEXT_OR_CSV");
        enumStr = String.join("_", CodegenNamingUtils.splitOnWordBoundaries(enumStr));
        return StringUtils.upperCase(enumStr);
    }

    private static class Visitor extends JavaIsoVisitor<ExecutionContext> {

        @Override
        public J.FieldAccess visitFieldAccess(J.FieldAccess fieldAccess, ExecutionContext ctx) {
            fieldAccess = super.visitFieldAccess(fieldAccess, ctx);

            if (isV2EnumValue(fieldAccess)) {
                String v2Name = v2Casing(fieldAccess.getSimpleName());
                ENUMS.add(v2Name);
                return fieldAccess.withName(fieldAccess.getName().withSimpleName(v2Name));
            }
            return fieldAccess;
        }

        @Override
        public J.Identifier visitIdentifier(J.Identifier identifier, ExecutionContext ctx) {
            identifier = super.visitIdentifier(identifier, ctx);

            if (ENUMS.contains(identifier.getSimpleName())) {
                return identifier.withFieldType(identifier.getFieldType().withName(identifier.getSimpleName()));
            }
            return identifier;
        }

        public boolean isV2EnumValue(J.FieldAccess fieldAccess) {
            Expression target = fieldAccess.getTarget();
            JavaType type = target.getType();
            JavaType.FullyQualified fullyQualified = TypeUtils.asFullyQualified(type);
            if (fullyQualified != null) {
                return SdkTypeUtils.isV2ModelClass(type)
                       && fullyQualified.getKind() == JavaType.FullyQualified.Kind.Enum;
            }
            return false;
        }
    }
}
